from pathlib import Path
import numpy as np, pandas as pd, json
ROOT=Path(__file__).resolve().parents[1]
def generate_healthcare_data(n=1000,seed=20261108):
 r=np.random.default_rng(seed); age=np.clip(r.normal(53,16,n),18,90).round().astype(int); bmi=np.clip(r.normal(27,5,n),16,48); smoking=r.choice(['never','former','current'],n,p=[.51,.29,.20]); family=r.binomial(1,.23,n); exposure=r.binomial(1,.18,n); inflammation=r.normal(0,1,n)+.018*(age-50)+.30*(smoking=='current'); latent=.035*(age-50)+.58*family+.4*exposure+.36*inflammation+.25*(smoking=='current')+.3*np.sin(age/9)+r.normal(0,.65,n)-1.35; prob=1/(1+np.exp(-latent)); cancer=r.binomial(1,prob); marker=np.maximum(.1,2.4+1.6*cancer+.45*inflammation+r.normal(0,1.5,n)); imaging=np.maximum(.1,3.8+1.9*cancer+.30*marker+r.normal(0,2.0,n)); crp=np.maximum(.05,3+.8*inflammation+1.0*cancer+r.normal(0,1.2,n)); symptoms=r.poisson(np.clip(.75+.75*cancer+.12*marker,.1,5)); severity=np.where(symptoms<2,'low',np.where(symptoms<4,'moderate','high')); referral=r.choice(['routine','primary_care','specialist'],n,p=[.46,.37,.17]); temp=np.clip(r.normal(36.8+.12*inflammation,.4,n),35,40); screenings=r.poisson(np.maximum(.2,1.4+.015*(age-40))); consultation=r.poisson(1+symptoms*.5); return pd.DataFrame(dict(patient_id=[f'PAT-{i:04d}' for i in range(1,n+1)],age=age,bmi=np.round(bmi,2),smoking_status=smoking,family_history=family,exposure_history=exposure,prior_screenings=screenings,symptom_count=symptoms,symptom_severity=severity,referral_source=referral,prior_consultations=consultation,biomarker_level=np.round(marker,3),imaging_score=np.round(imaging,3),inflammation_marker=np.round(crp,3),temperature_c=np.round(temp,2),cancer_status=cancer))
def generate_retail_data(seed=20261109):
 r=np.random.default_rng(seed); dates=pd.date_range('2026-01-01',periods=100); categories=['electronics','home','beauty','sports','books']; rows=[]; base=r.uniform(12,65,10); costs=base*r.uniform(.45,.75,10); trend=r.normal(0,.13,100).cumsum();
 for d,date in enumerate(dates):
  weekend=int(date.dayofweek>=5); shared=r.normal(0,.13); promo=int(d%21 in (4,5,6));
  for j in range(10):
   price=round(float(base[j]*(1+.025*np.sin(d/17))),2); discount=float(r.choice([0,.05,.10,.20],p=[.5,.25,.2,.05])) if promo else float(r.choice([0,.05],p=[.9,.1])); ad=round(float(r.gamma(2,7)*(1+promo)),2); inventory=int(r.integers(10,65)); competitor=round(float(r.normal(1,.08)),3); shipping=float(r.choice([0,3.99,6.99])); rating=round(float(np.clip(r.normal(4.1,.4),2.5,5)),2); delay=int(r.random()<.08); temp=round(float(22+5*np.sin(d/18)+r.normal(0,2)),2); demand_mean=np.exp(2.7+.16*(j%5)+.22*weekend+.25*promo+.65*discount+.12*np.log1p(ad)-.7*np.log(price/30)+.12*(rating-4)+shared+trend[d]-.15*delay); demand=int(r.poisson(min(demand_mean,100))); units=min(demand,inventory); returns=int(r.binomial(units,.04)); gross=round(units*price,2); disc=round(gross*discount,2); net=round(gross-disc-returns*price*(1-discount),2); margin=round(net-(units-returns)*costs[j],2); rows.append((f'SALE-{d*10+j+1:04d}',date.strftime('%Y-%m-%d'),f'PROD-{j+1:02d}',categories[j%5],price,round(float(costs[j]),2),inventory,discount,ad,'campaign' if promo else 'none',shipping,rating,competitor,delay,weekend,promo,temp,units,returns,gross,disc,net,margin))
 cols=['sale_id','date','product_id','category','unit_price','unit_cost','inventory_available','discount_pct','advertising_spend','promotion_type','shipping_fee','customer_rating','competitor_price_index','delivery_delay','is_weekend','promotion_period','temperature_c','units_sold','return_count','gross_revenue','discount_amount','net_sales_revenue','estimated_gross_margin']; return pd.DataFrame(rows,columns=cols)
def main():
 a=generate_healthcare_data(); b=generate_retail_data(); (ROOT/'data/clean').mkdir(parents=True,exist_ok=True); a.to_csv(ROOT/'data/clean/healthcare_clean.csv',index=False,lineterminator='\n'); b.to_csv(ROOT/'data/clean/retail_clean.csv',index=False,lineterminator='\n')
 config={'healthcare_n':1000,'retail_n':1000,'healthcare_seed':20261108,'retail_seed':20261109,'defect_seed':20261110,'retail_start':'2026-01-01','retail_days':100,'products':10,'observation_unit':'product-store-day, single store','healthcare_unit':'one patient assessment','healthcare_prevalence':float(a.cancer_status.mean()),'generation':'See documented explicit stochastic equations in source and docs; no real-world calibration','schemas':{'healthcare':list(a.columns),'retail':list(b.columns)}}; (ROOT/'data/metadata/generation_config.json').write_text(json.dumps(config,indent=2)); return a,b
if __name__=='__main__': main()
